import torch
import torch.nn as nn

torch.manual_seed(42)
N, C_in, C_out = 2, 3, 4
D_in, H_in, W_in = 4, 5, 5
K, stride, pad = 3, 2, 1

ref = nn.ConvTranspose3d(C_in, C_out, K, stride=stride, padding=pad, bias=True)
x = torch.randn(N, C_in, D_in, H_in, W_in)
with torch.no_grad():
    ref_out = ref(x)

weight = ref.weight  # (C_in, C_out, K, K, K)
bias = ref.bias      # (C_out,)
D_out, H_out, W_out = ref_out.shape[2:]

# Test: no kernel flip
manual1 = torch.zeros_like(ref_out)
for n_idx in range(N):
    for co in range(C_out):
        for dp in range(D_out):
            for hp in range(H_out):
                for wp in range(W_out):
                    v = bias[co].item()
                    for ci in range(C_in):
                        for kd in range(K):
                            db = dp + pad - kd
                            if db % stride == 0:
                                di = db // stride
                                if 0 <= di < D_in:
                                    for kh in range(K):
                                        hb = hp + pad - kh
                                        if hb % stride == 0:
                                            hi = hb // stride
                                            if 0 <= hi < H_in:
                                                for kw in range(K):
                                                    wb = wp + pad - kw
                                                    if wb % stride == 0:
                                                        wi = wb // stride
                                                        if 0 <= wi < W_in:
                                                            v += x[n_idx,ci,di,hi,wi].item() * weight[ci,co,kd,kh,kw].item()
                    manual1[n_idx,co,dp,hp,wp] = v
d1 = (ref_out - manual1).abs().max().item()
print(f'No flip max diff: {d1:.6f}')

# Test: with kernel flip
manual2 = torch.zeros_like(ref_out)
for n_idx in range(N):
    for co in range(C_out):
        for dp in range(D_out):
            for hp in range(H_out):
                for wp in range(W_out):
                    v = bias[co].item()
                    for ci in range(C_in):
                        for kd in range(K):
                            db = dp + pad - kd
                            if db % stride == 0:
                                di = db // stride
                                if 0 <= di < D_in:
                                    for kh in range(K):
                                        hb = hp + pad - kh
                                        if hb % stride == 0:
                                            hi = hb // stride
                                            if 0 <= hi < H_in:
                                                for kw in range(K):
                                                    wb = wp + pad - kw
                                                    if wb % stride == 0:
                                                        wi = wb // stride
                                                        if 0 <= wi < W_in:
                                                            v += x[n_idx,ci,di,hi,wi].item() * weight[ci,co,K-1-kd,K-1-kh,K-1-kw].item()
                    manual2[n_idx,co,dp,hp,wp] = v
d2 = (ref_out - manual2).abs().max().item()
print(f'Flipped max diff: {d2:.6f}')
print(f'Ref mean/std: {ref_out.mean():.4f} / {ref_out.std():.4f}')
print(f'No-flip mean/std: {manual1.mean():.4f} / {manual1.std():.4f}')
print(f'Flipped mean/std: {manual2.mean():.4f} / {manual2.std():.4f}')
